{
  "case_id": "xsu_sg_001_general_conditions",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "not_met", "reason": "Svaret opfinder to former for tillæg (tilrettelæggelsesstillæg og meromkostningstillæg), som ikke findes i kilderne. Det udelader de tre centrale betingelser: videregående uddannelse eller dansk EUD, varig funktionsnedsættelse med meget betydelige begrænsninger i erhvervsevnen, og at de almindelige SU-betingelser skal være opfyldt. Det angiver i stedet 'erhvervsaktiverende dagpenge eller studiepenge' som betingelse, hvilket er forkert. Det er væsentlige juridiske fejl."},
    "c02_required_elements_complete": {"label": "not_met", "reason": "Ingen af de tre kritiske elementer er med: (1) almindelige SU-/slutlånsbetingelser og udbetaling sammen med SU-stipendium/slutlån, (2) indskrevet på og følger videregående uddannelse eller dansk EUD, (3) varig funktionsnedsættelse med meget betydelige begrænsninger i evnen til erhvervsarbejde."},
    "c03_direct_relevance": {"label": "not_met", "reason": "Spørgsmålet gælder betingelserne for SU-handicaptillæg. Svaret nævner ikke de faktiske betingelser og bygger på en forkert opdeling i to tillægstyper og forkerte betingelser, så det besvarer ikke de væsentlige dele af spørgsmålet."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret angiver ingen identificerbar kilde (lovbestemmelse, vejledning eller bekendtgørelse)."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Der er ikke angivet nogen kilde, så kildens gyldighed kan ikke vurderes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Der er ikke angivet nogen kilde, så kildestøtte til påstandene kan ikke vurderes."},
    "c07_no_unsupported_legal_additions": {"label": "not_met", "reason": "Svaret tilføjer uunderstøttede regler: to former for tillæg, krav om erhvervsaktiverende dagpenge eller studiepenge, krav om særlige hjælpemidler og krav om ekstra udgifter. Intet af dette findes i kildematerialet."},
    "c08_qualifications_and_exceptions": {"label": "not_met", "reason": "Svaret bevarer ikke de relevante afgrænsninger: varig funktionsnedsættelse, meget betydelige begrænsninger, dansk EUD (inkl. EUX) og at erhvervslignende uddannelse i udlandet ikke er omfattet. Det angiver heller ikke, at svaret kun er et overblik."},
    "c09_reasoning_coherence": {"label": "not_met", "reason": "Svaret er internt inkonsekvent. Det siger, at begge tillæg kræver dagpenge eller studiepenge, men skitserer derefter forskellige betingelser. Præmisserne er uden grundlag i reglerne, så konklusionen følger ikke af en gyldig juridisk fremstilling."},
    "c10_legal_modality_precision": {"label": "not_met", "reason": "Svaret præsenterer opfundne betingelser som absolutte krav ('skal have'), selvom de ikke findes i kilderne. Det gengiver ikke kildernes krav korrekt."}
  },
  "xhaile_coverage": {
    "A1": {"label": "no", "reason": "De almindelige betingelser for SU eller slutlån nævnes ikke. 'Erhvervsaktiverende dagpenge eller studiepenge' er ikke det samme."},
    "A2": {"label": "no", "reason": "Kravet om videregående uddannelse eller dansk EUD nævnes ikke. Svaret omtaler kun 'din uddannelse' generelt."},
    "A3": {"label": "no", "reason": "Kravet om varig fysisk eller psykisk funktionsnedsættelse med meget betydelige begrænsninger i evnen til erhvervsarbejde mangler. Svaret nævner kun 'begrænsning' knyttet til hjælpemidler og 'handicap eller sygdom' knyttet til ekstra udgifter."},
    "A4": {"label": "no", "reason": "Kravet om at være indskrevet på og gennemgå en uddannelse, der berettiger til SU eller slutlån, nævnes ikke."},
    "A6": {"label": "no", "reason": "Dansk EUD, EUX og udelukkelsen af erhvervslignende uddannelse i udlandet nævnes ikke."}
  },
  "overall_notes": "Svaret er juridisk forkert og mangelfuldt. Det opfinder en opdeling i to tillægstyper og forkerte betingelser og udelader alle tre centrale betingelser. Det angiver ingen kilde, så C04 er not_met, og C05 og C06 er not_assessable."
}

